<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('project_tasks.view');$pdo=db();$projectId=(int)($_GET['project_id']??0);$project=$projectId?pm_fetch_project($pdo,$projectId):null;$projects=pm_project_options($pdo);$pageTitle=$project?'Gantt · '.$project['name']:'Gantt global';$where=$projectId?'WHERE t.project_id=?':"WHERE p.status IN ('planning','active','on_hold')";$s=$pdo->prepare("SELECT t.*,p.name project_name,p.color project_color,u.name assigned_name FROM project_tasks t JOIN projects p ON p.id=t.project_id LEFT JOIN users u ON u.id=t.assigned_to $where AND t.start_date IS NOT NULL AND t.due_date IS NOT NULL ORDER BY t.start_date,t.due_date");$s->execute($projectId?[$projectId]:[]);$tasks=$s->fetchAll();$min=null;$max=null;foreach($tasks as$t){$a=new DateTimeImmutable($t['start_date']);$b=new DateTimeImmutable($t['due_date']);$min=$min===null||$a<$min?$a:$min;$max=$max===null||$b>$max?$b:$max;}$min??=new DateTimeImmutable('first day of this month');$max??=$min->modify('+30 days');if($max<=$min)$max=$min->modify('+1 day');$days=max(1,(int)$min->diff($max)->days+1);require __DIR__.'/includes/header.php';if($project)echo pm_project_tabs($projectId,'gantt');?>
<div class="project-hero compact"><div><span class="eyebrow">GANTT / PROJECT</span><h2><?=e($project?$project['name']:'Cronograma global')?></h2><p>Plan visual de tareas, fechas, duración, responsables y avance.</p></div><form method="get"><select name="project_id" onchange="this.form.submit()"><option value="0">Todos los proyectos activos</option><?php foreach($projects as$p):?><option value="<?=$p['id']?>" <?=$projectId===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></form></div>
<section class="panel"><div class="panel-header"><div><h2>Cronograma</h2><span class="table-sub"><?=e($min->format('d/m/Y'))?> → <?=e($max->format('d/m/Y'))?> · <?=$days?> días</span></div></div><div class="pm-gantt-wrap"><div class="pm-gantt" style="--gantt-days:<?=$days?>"><?php if(!$tasks):?><div class="empty">Agrega fecha de inicio y entrega a las tareas para verlas aquí.</div><?php endif;?><?php foreach($tasks as$t):$a=new DateTimeImmutable($t['start_date']);$b=new DateTimeImmutable($t['due_date']);$start=(int)$min->diff($a)->format('%r%a');$dur=max(1,(int)$a->diff($b)->days+1);$left=max(0,$start)/$days*100;$width=min(100-$left,$dur/$days*100);?><div class="pm-gantt-row"><div class="pm-gantt-label"><strong><a href="project_task_form.php?id=<?=$t['id']?>"><?=e($t['title'])?></a></strong><small><?=e($t['project_name'])?> · <?=e($t['assigned_name']?:'Sin asignar')?></small></div><div class="pm-gantt-track"><span class="pm-gantt-bar" style="left:<?=$left?>%;width:<?=$width?>%;--project-color:<?=e($t['project_color'])?>"><b><?=e($a->format('d/m'))?>–<?=e($b->format('d/m'))?></b><i style="width:<?=(int)$t['progress']?>%"></i></span></div></div><?php endforeach;?></div></div></section>
<?php require __DIR__.'/includes/footer.php';?>
